/* Generic, independently authored complex algebra for exact near-field model. */
(function(root,factory){const api=factory(typeof module==='object'&&module.exports?require('./linalg.js'):root.CrbLinearAlgebra,typeof module==='object'&&module.exports?require('./hermitian.js'):root.JointHermitian);if(typeof module==='object'&&module.exports)module.exports=api;else root.NearfieldNumerics=api;})(typeof self!=='undefined'?self:globalThis,function(LA,H){
'use strict';
function identity(n){const A=new Float64Array(2*n*n);for(let i=0;i<n;i++)A[2*(i*n+i)]=1;return A;}
function herm(A,n){const B=new Float64Array(A.length);for(let i=0;i<n;i++)for(let j=0;j<n;j++){B[2*(i*n+j)]=(A[2*(i*n+j)]+A[2*(j*n+i)])/2;B[2*(i*n+j)+1]=(A[2*(i*n+j)+1]-A[2*(j*n+i)+1])/2;}return B;}
function complexChol(A,n){const L=new Float64Array(A.length);let logdet=0,minPivot=Infinity,maxPivot=0;for(let i=0;i<n;i++)for(let j=0;j<=i;j++){let re=A[2*(i*n+j)],im=A[2*(i*n+j)+1];for(let k=0;k<j;k++){const a=L[2*(i*n+k)],b=L[2*(i*n+k)+1],c=L[2*(j*n+k)],d=L[2*(j*n+k)+1];re-=a*c+b*d;im-=b*c-a*d;}if(i===j){if(!(re>0)||!Number.isFinite(re))return null;L[2*(i*n+i)]=Math.sqrt(re);logdet+=Math.log(re);minPivot=Math.min(minPivot,re);maxPivot=Math.max(maxPivot,re);}else{L[2*(i*n+j)]=re/L[2*(j*n+j)];L[2*(i*n+j)+1]=im/L[2*(j*n+j)];}}return {L,logdet,minPivot,maxPivot};}
function complexSolve(L,b,n,c=1){const x=new Float64Array(b);for(let i=0;i<n;i++)for(let j=0;j<c;j++){let re=x[2*(i*c+j)],im=x[2*(i*c+j)+1];for(let k=0;k<i;k++){const a=L[2*(i*n+k)],b=L[2*(i*n+k)+1],u=x[2*(k*c+j)],v=x[2*(k*c+j)+1];re-=a*u-b*v;im-=a*v+b*u;}x[2*(i*c+j)]=re/L[2*(i*n+i)];x[2*(i*c+j)+1]=im/L[2*(i*n+i)];}for(let i=n-1;i>=0;i--)for(let j=0;j<c;j++){let re=x[2*(i*c+j)],im=x[2*(i*c+j)+1];for(let k=i+1;k<n;k++){const a=L[2*(k*n+i)],b=-L[2*(k*n+i)+1],u=x[2*(k*c+j)],v=x[2*(k*c+j)+1];re-=a*u-b*v;im-=a*v+b*u;}x[2*(i*c+j)]=re/L[2*(i*n+i)];x[2*(i*c+j)+1]=im/L[2*(i*n+i)];}return x;}
function inverse(A,n){const ch=complexChol(A,n);if(!ch)return null;return {...ch,inverse:herm(complexSolve(ch.L,identity(n),n,n),n)};}
function realInverse(A,n){let L;try{L=LA.chol(A,n,0);}catch{return null;}const inv=new Float64Array(n*n);for(let i=0;i<n;i++){const e=new Float64Array(n);e[i]=1;const c=LA.cholSolve(L,e,n);for(let j=0;j<n;j++)inv[j*n+i]=c[j];}return {L,inverse:inv,logdet:2*Array.from({length:n},(_,i)=>Math.log(L[i*n+i])).reduce((a,b)=>a+b,0)};}
function spectral(A,m){const n=2*m,R=new Float64Array(n*n);for(let i=0;i<m;i++)for(let j=0;j<m;j++){const a=A[2*(i*m+j)],b=A[2*(i*m+j)+1];R[i*n+j]=R[(i+m)*n+j+m]=a;R[i*n+j+m]=-b;R[(i+m)*n+j]=b;}const e=H.eigSymmetric(R,n);if(!e.converged)throw Error('eigen_decomposition_failed');return e;}
function sum(Ms){const a=new Float64Array(Ms[0].length);for(const M of Ms)for(let j=0;j<a.length;j++)a[j]+=M[j];return a;}
function scale(A,s){return Float64Array.from(A,v=>v*s);}
function unpack(M,r,c){if(!M||!Array.isArray(M.re)||!Array.isArray(M.im)||M.re.length!==r||M.im.length!==r)throw Error('complex_shape');const A=new Float64Array(2*r*c);for(let i=0;i<r;i++){if(!Array.isArray(M.re[i])||!Array.isArray(M.im[i])||M.re[i].length!==c||M.im[i].length!==c)throw Error('complex_shape');for(let j=0;j<c;j++){const re=M.re[i][j],im=M.im[i][j];if(typeof re!=='number'||typeof im!=='number'||!Number.isFinite(re)||!Number.isFinite(im))throw Error('nonfinite_complex_input');A[2*(i*c+j)]=re;A[2*(i*c+j)+1]=im;}}return A;}
function pack(A,r,c){const p=LA.pack(A,r,c);return {re:p.real,im:p.imag};}
return {...LA,identity,herm,complexChol,complexSolve,inverse,realInverse,spectral,sum,scale,unpack,pack,projectPSD:H.projectPSD,eigSymmetric:H.eigSymmetric};
});
